/**
 * Offline mdi icon collection — closes the CSP-blocked runtime fetch hole.
 *
 * The @thatopen vendor UI and our shell render <iconify-icon> elements;
 * without a locally registered collection the iconify runtime fetches each
 * icon from its public icon CDNs (and mirrors) — blocked by the app CSP in
 * production and a hole in the no-third-party-runtime-dependency story
 * (see the pwa-offline row in feature-maturity.ts).
 *
 * mdi-offline-icons.json is generated by scripts/gen-mdi-offline.py from
 * @iconify-json/mdi and contains exactly the icons used in src/ and the
 * vendor dists (re-run the script after adding a new icon usage).
 * addCollection seeds the same shared storage the vendor's iconify-icon
 * instance reads, so no network request is ever made for these icons.
 */
import { addCollection } from "iconify-icon";
import mdiOffline from "./mdi-offline-icons.json";

export function setupOfflineIcons(): number {
  const ok = addCollection(mdiOffline as never);
  if (!ok) console.warn("[icons] offline mdi collection rejected — check iconify-icon version");
  return Object.keys((mdiOffline as { icons: Record<string, unknown> }).icons).length;
}
